// AVTOMATIK YARATILGAN: scripts/gen_onboarding.py. Qo'lda tahrirlamang.
// Onboarding slaydlari (PNG, base64).

export const ONBOARDING_SLIDES: string[] = [
  "",
  "",
  "",
  "",
];

export function onboardingSlide(index: number): Uint8Array | null {
  const b64 = ONBOARDING_SLIDES[index];
  if (!b64) return null;
  const binary = atob(b64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
  return bytes;
}
